// SPDX-License-Identifier: MIT
// Nova Atelier — Features card 2 label
import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { mix, uv, vec3, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const surfaceColor = new Color(colors.surface);
  const paperColor = new Color(colors.paper);
  const accentColor = new Color(colors.accent);

  // --- Label card panel: subtle engineered-gradient surface with grain ---
  const panelW = 2.4;
  const panelH = 0.7;
  const panelGeo = new PlaneGeometry(panelW, panelH);
  const panelMat = new MeshBasicNodeMaterial({ transparent: true });

  // vertical engineered gradient: surface -> ink, with accent hairline top edge
  const grad = mix(
    vec3(surfaceColor),
    vec3(new Color(colors.ink)),
    uv().y.smoothstep(0.0, 1.0)
  );
  // accent top hairline
  const hairline = smoothstep(0.92, 0.965, uv().y) * 0.85;
  const accentVec = vec3(accentColor);
  const baseColor = mix(grad, accentVec, hairline);

  // subtle grain shimmer
  const grain = smoothstep(0.4, 0.6, uv().x.add(uv().y).sin().mul(7.3).add(time.mul(0.15))).mul(0.03);
  panelMat.colorNode = baseColor.add(grain);
  panelMat.opacityNode = uniform(0);

  const panel = new Mesh(panelGeo, panelMat);
  panel.position.set(0, 0, -0.01);
  group.add(panel);

  // --- Text content ---
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  for (const item of items) {
    const fs = item.typography?.fontSize ?? 39;
    // map px-ish to scene units: label scale
    const sceneFs = (fs / 100) * 0.34;
    const txt = ctx.fontAtlas.createText(String(item.text), {
      fontSize: sceneFs,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 0.04 * sceneFs * 100,
    });
    txt.position.set(0, 0, 0.02);
    txt.userData.targetOpacity = 1;
    group.add(txt);
    textMeshes.push(txt);
  }

  // Fallback if no textContent items but label copy expected
  if (textMeshes.length === 0) {
    const txt = ctx.fontAtlas.createText('FEATURES 2', {
      fontSize: 0.13,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 6,
    });
    txt.position.set(0, 0, 0.02);
    group.add(txt);
    textMeshes.push(txt);
  }

  // --- Entrance: rise-in + fade ---
  const tl = gsap.timeline();
  group.position.y = 0 + 0.4;
  tl.to(group.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(panelMat.userData, {}, 0); // noop-safe
  // fade panel opacity
  const opObj = { v: 0 };
  tl.to(opObj, {
    v: 1,
    duration: 0.6,
    ease: 'power2.out',
    onUpdate: () => { panelMat.opacityNode.value = opObj.v; },
  }, 0);
  // text fade-up handled via material opacity if available
  for (const t of textMeshes) {
    const o = { v: 0 };
    tl.to(o, {
      v: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => {
        t.traverse?.((c) => {
          if (c.material && c.material.opacity !== undefined) {
            c.material.transparent = true;
            c.material.opacity = o.v;
          }
        });
      },
    }, 0.08);
  }

  // --- Handlers (none specified, but reserve surface) ---
  group.userData.handlers = {};

  // --- Cleanup ---
  group.userData.cleanup = () => {
    tl.kill();
    panelGeo.dispose();
    panelMat.dispose();
    for (const t of textMeshes) {
      t.traverse?.((c) => {
        if (c.geometry) c.geometry.dispose();
        if (c.material) c.material.dispose();
      });
    }
  };

  return group;
}
